LNLSGRS.definition_yaml:
LNLSGRS:
  title: LOANS AND LEASES, GROSS
  description:
  type: number
  x-source-mapping:
    - formula:
        type: raw
        parameters:
          script: |
            def LNLSGR = ctx.LNLSGR ?: 0;
            def LNCONTRA = ctx.LNCONTRA ?: 0;
            def UNINC = ctx.UNINC ?: 0;
            def LNLS = ctx.LNLS ?: 0;
            if (Integer.parseInt(ctx.REPYEAR) < 1996) {
              ctx.LNLSGRS = LNLSGR + LNCONTRA - UNINC;
            } else { 
              ctx.LNLSGRS = LNLS;
            }
